def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather opponent's moves using tuple indexing only.
    opp = [history[i][1] for i in range(n)]
    me = [history[i][0] for i in range(n)]

    opp_c = 0
    opp_d = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
        else:
            opp_d += 1

    my_c = 0
    my_d = 0
    for x in me:
        if x == 'C':
            my_c += 1
        else:
            my_d += 1

    last_my = me[-1]
    last_opp = opp[-1]

    # helper inline: recent defection counts
    k10 = n if n < 10 else 10
    recent_opp_d10 = 0
    recent_my_d10 = 0
    for i in range(n - k10, n):
        if opp[i] == 'D':
            recent_opp_d10 += 1
        if me[i] == 'D':
            recent_my_d10 += 1

    k5 = n if n < 5 else 5
    recent_opp_d5 = 0
    for i in range(n - k5, n):
        if opp[i] == 'D':
            recent_opp_d5 += 1

    # Opening: cooperate, but if opponent opens with D, punish.
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    # Strong defector detection: mostly defect if opponent almost always defects.
    if n >= 6 and opp_d * 3 >= n * 2:
        return 'D'

    # Occasionally probe/testing for pure cooperators after enough evidence.
    if n >= 8 and opp_d == 0:
        # Very cooperative opponent; mix small exploitation with cooperation.
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Endgame: exploit cooperative opponents, but avoid mutual defection vs defectors.
    if n >= 90:
        if opp_c * 5 >= n * 3:
            return 'D'
        if opp_d * 2 >= n:
            return 'D'
        return 'C'

    # Late game: squeeze cooperators.
    if n >= 80 and opp_c * 4 >= n * 3:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # If opponent just defected after we cooperated -> retaliate.
    if last_opp == 'D':
        if last_my == 'C':
            # If opponent rarely defects, sometimes forgive to restore CC.
            if opp_d <= 1 or (opp_d * 5 <= n):
                if rng.random() < 0.35:
                    return 'C'
            return 'D'
        else:
            # Opponent defected after our defection; continue if they keep it up.
            if recent_opp_d5 >= 4:
                return 'D'
            if recent_opp_d10 >= 6:
                return 'D'
            # Try to restore cooperation occasionally if opponent was mostly nice.
            if opp_d * 4 <= n:
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            return 'D' if rng.random() < 0.7 else 'C'

    # Opponent cooperated.
    # If we've been defecting a lot and opponent keeps cooperating, exploit more.
    if last_my == 'D' and last_opp == 'C':
        if opp_d == 0 and n >= 6:
            return 'D'
        if opp_d * 5 <= n and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Default: cooperate, but probe occasionally.
    if n >= 15 and opp_d * 5 <= n and rng.random() < 0.08:
        return 'D'
    return 'C'
